CREATE TEMPORARY VIEW user_exp_mapping_${grass_region_without_quote} AS
SELECT
    user_id
    ,exp_group_id
FROM
    srdi_mart.dim_sr_data_warehouse_abtest_user_group
WHERE
    grass_region = ${grass_region}
    AND local_date = ${local_date}
    AND is_assignment_log = 1
    AND experiment_id = 100655;

--sql_divide_splitter--

CREATE TEMPORARY VIEW dwd_impression_${grass_region_without_quote} AS 
SELECT
    item_id
    ,request_id 
FROM 
    srdi_mart.dwd_sr_data_warehouse_search
WHERE
    grass_region = ${grass_region}
    AND local_date = ${local_date}
    AND user_id > 0
    AND target_type in ('item','video','livestream')
    AND page_section IS NULL 
    AND page_type IN ('global_search', 'search_in_pdp', 'search_prefill')
    AND entrance_keyword_type = 'llmsim'
    AND operation = 'impression'
GROUP BY 
    1,2;

--sql_divide_splitter--

CREATE TEMPORARY VIEW ads_performance_${grass_region_without_quote} AS 
SELECT 
    user_id
    ,trim(lower(query)) as keyword
    ,sum(coalesce(expenditure_amt_usd, 0)) as ads_revenue
    ,sum(IF(b.item_id IS NOT NULL,coalesce(expenditure_amt_usd, 0),0 ) ) as llm_ads_revenue
FROM mp_paidads.dwd_advertise_performance_di__reg_s0_live a
    LEFT JOIN dwd_impression_${grass_region_without_quote} b 
    ON a.raw_request_id = b.request_id
    AND a.item_id = b.item_id   
WHERE 
    grass_date = ${local_date}
    AND grass_region = ${grass_region}
    AND tz_type = 'local'
    AND entrance = 1 --global search
    AND user_id > 0
GROUP BY 1,2;

--sql_divide_splitter--

CREATE TEMPORARY VIEW be_log_llm_list_${grass_region_without_quote} AS
SELECT
    trim(lower(request_keyword)) AS keyword
FROM
    srdi_mart.dwd_sr_data_warehouse_search_be_log
WHERE
    local_date = ${local_date}
    AND grass_region = ${grass_region}
    AND is_nls_consult = 'true'
GROUP BY 
    1;

--sql_divide_splitter--

CREATE TEMPORARY VIEW dwd_raw_data_${grass_region_without_quote} AS
SELECT
    user_id
    ,TRIM(LOWER(keyword)) AS keyword
    ,module_keyword_type
    ,entrance_keyword_type
    ,target_type
    ,SUM(IF(operation = 'view', operation_cnt, NULL)) AS view_cnt
    ,SUM(IF(operation = 'impression', operation_cnt, NULL)) AS imp_cnt
    ,SUM(IF(operation = 'click', operation_cnt, NULL)) AS click_cnt
    ,SUM(IF(operation = 'order', operation_cnt, NULL)) AS order_cnt
    ,SUM(IF(operation = 'order', place_order_gmv, NULL)) AS gmv
FROM
    srdi_mart.dwd_sr_data_warehouse_search
WHERE
    grass_region = ${grass_region}
    AND local_date = ${local_date}
    AND user_id > 0
    AND page_type IN ('global_search', 'search_in_pdp', 'search_prefill')
    AND page_section IS NULL
    AND ((operation = 'click' AND original_operation = 'click') OR operation IN ('view', 'impression', 'order'))
GROUP BY
    1,2,3,4,5;

--sql_divide_splitter--

CREATE TEMPORARY VIEW dws_srp_${grass_region_without_quote} AS 
SELECT
    user_id
    ,keyword
    ,SUM(IF(module_keyword_type = 'llmsim' AND target_type = 'related_search', imp_cnt, 0)) AS llm_rs_imp_cnt
    ,SUM(IF(module_keyword_type = 'llmsim' AND target_type = 'related_search', click_cnt, 0)) AS llm_rs_click_cnt

    ,SUM(IF(target_type IN ('item','video','livestream'), imp_cnt, 0)) AS total_imp_cnt
    ,SUM(IF(target_type IN ('item','video','livestream'), click_cnt, 0)) AS total_click_cnt
    ,SUM(IF(target_type IN ('item','video','livestream'), order_cnt, 0)) AS total_order_cnt
    ,SUM(IF(target_type IN ('item','video','livestream'), gmv, 0)) AS total_gmv
    
    ,SUM(IF(target_type IN ('no_recall_general'), imp_cnt, 0)) AS no_recall_imp_cnt
    ,SUM(IF(entrance_keyword_type = 'llmsim' AND target_type IN ('item','video','livestream'), imp_cnt, 0)) AS llm_imp_cnt
    ,SUM(IF(entrance_keyword_type = 'llmsim' AND target_type IN ('item','video','livestream'), click_cnt, 0)) AS llm_click_cnt
    ,SUM(IF(entrance_keyword_type = 'llmsim' AND target_type IN ('item','video','livestream'), order_cnt, 0)) AS llm_order_cnt
    ,SUM(IF(entrance_keyword_type = 'llmsim' AND target_type IN ('item','video','livestream'), gmv, 0)) AS llm_gmv
    ,MAX(CASE WHEN (view_cnt > 0) OR (imp_cnt > 0 AND target_type = 'no_recall_general') THEN 1 ELSE 0 END) AS contains_view_cnt
FROM
    dwd_raw_data_${grass_region_without_quote}
GROUP BY
    1,2;

--sql_divide_splitter--

CREATE TEMPORARY VIEW dws_srp_with_llm_${grass_region_without_quote} AS 
SELECT
    COALESCE(a.user_id, c.user_id) AS user_id
    ,COALESCE(a.keyword, c.keyword, b.keyword) AS keyword

    ,SUM(IF(b.keyword IS NOT NULL AND contains_view_cnt = 1, 1, 0)) AS llm_list
    ,SUM(IF(b.keyword IS NOT NULL AND contains_view_cnt = 1, no_recall_imp_cnt, 0)) AS llm_list_norecall_cnt
    ,SUM(IF(b.keyword IS NOT NULL AND contains_view_cnt = 1, total_imp_cnt, 0)) AS llm_list_imp_cnt
    ,SUM(IF(b.keyword IS NOT NULL AND contains_view_cnt = 1, total_click_cnt, 0)) AS llm_list_click_cnt
    ,SUM(IF(b.keyword IS NOT NULL AND contains_view_cnt = 1, total_order_cnt, 0)) AS llm_list_order_cnt
    ,SUM(IF(b.keyword IS NOT NULL AND contains_view_cnt = 1, total_gmv, 0)) AS llm_list_gmv
    ,SUM(IF(b.keyword IS NOT NULL AND contains_view_cnt = 1, ads_revenue, 0)) AS llm_list_ads_revenue

    ,SUM(llm_rs_click_cnt) AS llm_module_click_cnt
    ,SUM(llm_imp_cnt) AS llm_imp_cnt
    ,SUM(llm_click_cnt) AS llm_click_cnt
    ,SUM(llm_order_cnt) AS llm_order_cnt
    ,SUM(llm_gmv) AS llm_gmv
    ,SUM(llm_ads_revenue) AS llm_ads_revenue

    ,SUM(IF(contains_view_cnt = 1, llm_rs_imp_cnt, 0)) AS llm_rs_imp_cnt
    ,SUM(IF(contains_view_cnt = 1, llm_rs_click_cnt, 0)) AS llm_rs_click_cnt
    ,MAX(contains_view_cnt) AS contains_view_cnt
FROM
    dws_srp_${grass_region_without_quote} a
    FULL OUTER JOIN be_log_llm_list_${grass_region_without_quote} b 
        ON a.keyword = b.keyword
    FULL OUTER JOIN ads_performance_${grass_region_without_quote} c 
        ON a.keyword = c.keyword 
        AND a.user_id = c.user_id
GROUP BY 1,2;

--sql_divide_splitter--

CREATE TEMPORARY VIEW dws_srp_result_${grass_region_without_quote} AS
SELECT
    100655 AS experiment_id
    ,exp_group_id

    ,COUNT(DISTINCT IF(llm_list > 0, a.user_id, NULL)) AS llm_list_search_uu 
    ,COUNT(DISTINCT IF(llm_list > 0 AND a.keyword IS NOT NULL, (a.user_id, a.keyword), NULL)) AS llm_list_search_volume
    ,COUNT(DISTINCT IF(llm_list > 0 AND llm_list_click_cnt > 0 AND a.keyword IS NOT NULL, (a.user_id, a.keyword), NULL)) AS llm_list_success_volume
    ,COUNT(DISTINCT IF(llm_list > 0 AND llm_list_norecall_cnt > 0 AND a.keyword IS NOT NULL, (a.user_id, a.keyword), NULL)) AS llm_list_norecall_volume 
    ,SUM(IF(a.keyword IS NOT NULL,llm_list_imp_cnt,0)) AS llm_list_imp_cnt
    ,SUM(IF(a.keyword IS NOT NULL,llm_list_order_cnt,0)) AS llm_list_order_cnt
    ,SUM(IF(a.keyword IS NOT NULL,llm_list_click_cnt,0)) AS llm_list_click_cnt
    ,SUM(IF(a.keyword IS NOT NULL,llm_list_gmv,0)) AS llm_list_gmv
    ,SUM(IF(a.keyword IS NOT NULL,llm_list_ads_revenue,0)) AS llm_list_ads_revenue
    ,COUNT(DISTINCT IF(llm_list > 0, keyword, NULL)) AS llm_list_query
    
    ,COUNT(DISTINCT IF(llm_module_click_cnt > 0, (a.user_id, a.keyword), NULL)) AS llm_search_volume
    ,COUNT(DISTINCT IF(llm_click_cnt > 0, (a.user_id, a.keyword), NULL)) AS llm_success_volume
    ,SUM(llm_imp_cnt) AS llm_imp_cnt
    ,SUM(llm_click_cnt) AS llm_click_cnt
    ,SUM(llm_order_cnt) AS llm_order_cnt
    ,SUM(llm_gmv) AS llm_gmv
    ,SUM(llm_ads_revenue) AS llm_ads_revenue

    ,COUNT(DISTINCT IF(contains_view_cnt > 0, (a.user_id, a.keyword), NULL)) AS llm_rs_search_volume
    ,COUNT(DISTINCT IF(contains_view_cnt > 0, a.user_id, NULL)) AS llm_rs_search_uv
    ,SUM(llm_rs_imp_cnt) AS llm_rs_imp_cnt
    ,SUM(llm_rs_click_cnt) AS llm_rs_click_cnt
    ,COUNT(DISTINCT IF(llm_rs_imp_cnt > 0, a.user_id, NULL)) AS llm_rs_imp_uv
    ,COUNT(DISTINCT IF(llm_rs_click_cnt > 0, a.user_id, NULL)) AS llm_rs_clk_uv
    ,COUNT(DISTINCT IF(llm_rs_imp_cnt > 0, (a.user_id, a.keyword), NULL)) AS llm_rs_imp_volume
    ,COUNT(DISTINCT IF(llm_rs_click_cnt > 0, (a.user_id, a.keyword), NULL)) AS llm_rs_clk_volume
    ,COUNT(DISTINCT IF(llm_rs_imp_cnt > 0, a.keyword, NULL)) AS llm_rs_query_cnt
FROM
    dws_srp_with_llm_${grass_region_without_quote} a
    INNER JOIN user_exp_mapping_${grass_region_without_quote} b
    ON a.user_id = b.user_id
GROUP BY 
    1,2;

--sql_divide_splitter--

INSERT OVERWRITE TABLE ${schema}.dws_sr_data_warehouse_search_abtest_llm_rewrite_1d
PARTITION (
    grass_region = ${grass_region},
    local_date = ${local_date}
)
SELECT
    experiment_id
    ,exp_group_id

    ,llm_list_search_uu 
    ,llm_list_search_volume
    ,llm_list_success_volume
    ,llm_list_norecall_volume 
    ,llm_list_imp_cnt
    ,llm_list_order_cnt
    ,llm_list_click_cnt
    ,llm_list_gmv
    ,llm_list_ads_revenue
    ,llm_list_query
    
    ,llm_search_volume
    ,llm_imp_cnt
    ,llm_click_cnt
    ,llm_order_cnt
    ,llm_gmv
    ,llm_ads_revenue

    ,llm_rs_search_volume
    ,llm_rs_search_uv
    ,llm_rs_imp_cnt
    ,llm_rs_click_cnt
    ,llm_rs_imp_uv
    ,llm_rs_clk_uv
    ,llm_rs_imp_volume
    ,llm_rs_clk_volume
    ,llm_rs_query_cnt

    ,llm_success_volume
FROM
    dws_srp_result_${grass_region_without_quote};
